export const VERSION=1;
export const DAY=86400000;
export function localDate(stamp=new Date()){if(typeof stamp==='string'&&stamp.length===10)return stamp;const p=new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Mbabane',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(stamp));const v=t=>p.find(x=>x.type===t).value;return `${v('year')}-${v('month')}-${v('day')}`;}
export const todayISO=()=>localDate();
export const addDays=(d,n)=>new Date(Date.parse(d+'T12:00:00Z')+n*DAY).toISOString().slice(0,10);
export const daysBetween=(a,b)=>Math.round((Date.parse(b+'T12:00:00Z')-Date.parse(a+'T12:00:00Z'))/DAY);
export function avatarSVG(index=0){const bg=['#dceae2','#e9e2f2','#ece5da','#dce5ed'][index%4];return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="240" height="280" viewBox="0 0 240 280"><rect width="240" height="280" rx="16" fill="${bg}"/><circle cx="120" cy="104" r="43" fill="#778a80"/><path d="M38 260c0-66 30-105 82-105s82 39 82 105" fill="#6a7e73"/><text x="120" y="278" text-anchor="middle" font-family="sans-serif" font-size="10" fill="#47594e">SAMPLE IDENTITY PHOTO</text></svg>`);}
export function seedState(today=todayISO()){
  const names=[['Sibusiso','Dlamini'],['Nomsa','Maseko'],['Lihle','Nxumalo'],['Musa','Mamba'],['Thandeka','Ndlovu'],['Sipho','Mthethwa'],['Ayanda','Simelane'],['Bongani','Dube'],['Nokuthula','Khumalo'],['Mandla','Vilakati'],['Zanele','Hlophe'],['Themba','Shongwe']];
  const expiries=[29,12,29,-3,5,89,18,21,-8,25,7,14];
  const state={version:VERSION,members:[],payments:[],visits:[],denials:[],notices:[],hours:[],overrides:[],audit:[],plans:[{id:'monthly',name:'Monthly',days:30,price:350,available:true},{id:'quarterly',name:'Quarterly',days:90,price:900,available:true}]};
  names.forEach(([first,last],i)=>{const member={id:'M'+String(i+1).padStart(4,'0'),first,last,idType:'Passport',idNumber:'DEMO-'+(1001+i),photo:avatarSVG(i),account:i===7?'SUSPENDED':'ENABLED',registeredAt:addDays(today,-80-i),credentialsConfigured:true};state.members.push(member);const plan=state.plans[i===5?1:0],expiry=addDays(today,expiries[i]);state.payments.push({id:'P'+(i+1),memberId:member.id,planId:plan.id,amount:plan.price,paidAt:addDays(expiry,-plan.days+1)+'T09:00:00+02:00',receipt:'DEMO-'+String(1001+i),resultingExpiry:expiry,method:'CASH',actor:'staff-demo',confirmed:true});});
  const eligible=state.members.filter(m=>m.account==='ENABLED'&&membership(state,m,today).active);
  const counts=[8,12,13,10,14,8,11,12,9,15,8,13,10,7];
  for(let d=13;d>=0;d--){const date=addDays(today,-d);for(let j=0;j<counts[d];j++){const m=eligible[j%eligible.length];const hour=6+Math.floor(j*.7),min=(j*13)%60,stamp=`${date}T${String(hour).padStart(2,'0')}:${String(min).padStart(2,'0')}:00+02:00`;const isOpen=d===0&&j>=4;state.visits.push({id:'V'+(state.visits.length+1),memberId:m.id,checkedIn:stamp,checkedOut:isOpen?null:`${date}T${String(hour+1).padStart(2,'0')}:${String(min).padStart(2,'0')}:00+02:00`,confirmedBy:'staff-demo',checkedOutBy:isOpen?null:'staff-demo',source:isOpen?null:'MANUAL'});}}
  state.notices=[{id:'N1',message:'Studio floor maintenance',detail:'The studio will be unavailable in the morning. The weights and cardio areas remain open.',scope:'studio',starts:addDays(today,2),ends:addDays(today,2),publishedAt:today+'T08:00:00+02:00',cancelled:false,actor:'manager-demo'},{id:'N2',message:'Welcome to your next chapter',detail:'Our team is here to help you build a consistent routine. Please check in with the front desk when you arrive.',scope:'gym',starts:addDays(today,-5),ends:addDays(today,30),publishedAt:addDays(today,-5)+'T09:00:00+02:00',cancelled:false,actor:'manager-demo'}];
  for(const scope of ['gym','weights','cardio','studio'])for(let day=0;day<7;day++)state.hours.push({scope,day,open:day===0?'08:00':'05:30',close:day===0?'14:00':day===6?'17:00':'21:00',closed:false});
  state.audit=[{id:'AU1',actor:'manager-demo',action:'Published notice',entity:'N1',at:today+'T08:00:00+02:00'}];return state;
}
export function membership(state,m,today=todayISO()){const payment=state.payments.filter(p=>p.memberId===m.id&&p.confirmed!==false).at(-1);const plan=payment?state.plans.find(p=>p.id===payment.planId):null;const expiry=payment?.resultingExpiry||null;const days=expiry?Math.max(0,daysBetween(today,expiry)+1):0;return {payment,plan,expiry,days,active:days>0};}
export const openVisit=(s,id)=>s.visits.find(v=>v.memberId===id&&!v.checkedOut);
export const actorFor=role=>role==='manager'?'manager-demo':'staff-demo';
export const requireStaff=role=>{if(!['staff','manager'].includes(role))throw new Error('This action requires a staff workspace.');};
export const requireManager=role=>{if(role!=='manager')throw new Error('Only a manager can change notices and hours.');};
const uid=prefix=>prefix+Date.now().toString(36)+Math.random().toString(36).slice(2,6);
function paymentInput(s,input){const plan=s.plans.find(p=>p.id===input.planId&&p.available);if(!plan)throw new Error('Choose an available membership plan.');const receipt=String(input.receipt||'').trim();if(!receipt)throw new Error('Enter a receipt number.');if(s.payments.some(p=>p.receipt.toLowerCase()===receipt.toLowerCase()))throw new Error('That receipt number has already been used.');if(!input.cashConfirmed)throw new Error('Confirm that the cash payment was received.');return {plan,receipt};}
function makePayment(s,m,input,role,today){const {plan,receipt}=paymentInput(s,input),current=membership(s,m,today);return {id:uid('P'),memberId:m.id,planId:plan.id,amount:plan.price,paidAt:new Date().toISOString(),receipt,resultingExpiry:current.active?addDays(current.expiry,plan.days):addDays(today,plan.days-1),method:'CASH',actor:actorFor(role),confirmed:true};}
export function register(s,input,role,today=todayISO()){
  requireStaff(role);for(const key of ['first','last','idType','idNumber','photo','password'])if(!String(input[key]||'').trim())throw new Error('Complete all required registration fields, including the photo and password.');
  if(s.members.some(m=>m.idType===input.idType&&m.idNumber.toLowerCase()===String(input.idNumber).trim().toLowerCase()))throw new Error('A member with this ID type and number already exists.');
  paymentInput(s,input);
  const m={id:uid('M'),first:input.first.trim(),last:input.last.trim(),idType:input.idType,idNumber:input.idNumber.trim(),photo:input.photo,account:'ENABLED',registeredAt:today,credentialsConfigured:true};
  const p=makePayment(s,m,input,role,today);s.members.push(m);s.payments.push(p);return {member:m,payment:p};
}
export function renew(s,id,input,role,today=todayISO()){requireStaff(role);const m=s.members.find(x=>x.id===id);if(!m)throw new Error('Member not found.');const payment=makePayment(s,m,input,role,today);s.payments.push(payment);return payment;}
export function attemptCheckIn(s,identifier,photoConfirmed,role,today=todayISO()){
  requireStaff(role);const q=String(identifier).trim().toLowerCase();const m=s.members.find(m=>m.id.toLowerCase()===q||m.idNumber.toLowerCase()===q);let reason=!m?'Unknown identifier':m.account!=='ENABLED'?'Account suspended':!membership(s,m,today).active?'Membership expired':openVisit(s,m.id)?'Already checked in':!photoConfirmed?'Photo not confirmed':null;
  if(reason){const denial={id:uid('D'),memberId:m?.id||null,identifier:String(identifier),reason,at:new Date().toISOString(),actor:actorFor(role)};s.denials.push(denial);return {ok:false,reason,denial};}
  const visit={id:uid('V'),memberId:m.id,checkedIn:new Date().toISOString(),checkedOut:null,confirmedBy:actorFor(role),checkedOutBy:null,source:null};s.visits.push(visit);return {ok:true,visit,member:m};
}
export function checkOut(s,visitId,role){requireStaff(role);const v=s.visits.find(x=>x.id===visitId&&!x.checkedOut);if(!v)throw new Error('No open visit was found.');v.checkedOut=new Date().toISOString();v.checkedOutBy=actorFor(role);v.source='MANUAL';return v;}
function audit(s,role,action,entity){s.audit.push({id:uid('AU'),actor:actorFor(role),action,entity,at:new Date().toISOString()});}
export function publishNotice(s,input,role){requireManager(role);if(!input.message?.trim()||!input.starts||!input.ends)throw new Error('Enter a title and both notice dates.');if(input.ends<input.starts)throw new Error('The end date must be on or after the start date.');if(!['gym','weights','cardio','studio'].includes(input.scope))throw new Error('Choose a valid scope.');const n={id:uid('N'),message:input.message.trim(),detail:input.detail?.trim()||'',scope:input.scope,starts:input.starts,ends:input.ends,publishedAt:new Date().toISOString(),cancelled:false,actor:actorFor(role)};s.notices.push(n);audit(s,role,'Published notice',n.id);return n;}
export function cancelNotice(s,id,role){requireManager(role);const n=s.notices.find(x=>x.id===id);if(!n)throw new Error('Notice not found.');n.cancelled=true;n.lastEditedBy=actorFor(role);audit(s,role,'Cancelled notice',id);}
export const visibleNotices=(s,today=todayISO())=>s.notices.filter(n=>n.publishedAt&&!n.cancelled&&n.ends>=today).map(n=>({...n,status:n.starts>today?'Upcoming':'In effect'}));
export function saveHours(s,input,role){requireManager(role);if(!['gym','weights','cardio','studio'].includes(input.scope))throw new Error('Choose a valid scope.');if(!input.closed&&(!input.open||!input.close||input.open>=input.close))throw new Error('Closing time must be after opening time.');if(input.mode==='override'){if(!input.date)throw new Error('Choose an override date.');const i=s.overrides.findIndex(h=>h.scope===input.scope&&h.date===input.date);const v={scope:input.scope,date:input.date,open:input.open,close:input.close,closed:!!input.closed,changedBy:actorFor(role)};if(i<0)s.overrides.push(v);else s.overrides[i]=v;audit(s,role,'Changed date override',input.scope+':'+input.date);}else{const day=Number(input.day);if(!Number.isInteger(day)||day<0||day>6)throw new Error('Choose a weekday.');const i=s.hours.findIndex(h=>h.scope===input.scope&&h.day===day);const v={scope:input.scope,day,open:input.open,close:input.close,closed:!!input.closed};if(i<0)s.hours.push(v);else s.hours[i]=v;audit(s,role,'Changed weekly hours',input.scope+':'+day);}}
export function resolveHours(s,scope,date=todayISO()){return s.overrides.find(h=>h.scope===scope&&h.date===date)||s.hours.find(h=>h.scope===scope&&h.day===new Date(date+'T12:00:00Z').getUTCDay())||{closed:true,scope};}
export function summary(s,today=todayISO()){const visits=s.visits.filter(v=>localDate(v.checkedIn)===today);return {members:s.members.length,active:s.members.filter(m=>membership(s,m,today).active).length,entries:visits.length,inside:s.visits.filter(v=>!v.checkedOut).length,expiring:s.members.filter(m=>{const x=membership(s,m,today);return x.active&&x.days<=7;}).length};}
